mapper.select:
/* CastChknMapper.retrieveChknQueueRawList */ SELECT A.SMLT_ACTL_DT, B.PSG_FCLT_CD, SUBSTR(B.PSG_FCLT_CD, -3, 1) AS ISLAND, NVL(A.WTNG_PSG_CNT, 0) AS WTNG_PSG_CNT, NVL(A.TRNST_PSG_CNT, 0) AS TRNST_PSG_CNT, NVL(A.AVG_WTNG_HR, 0) AS WTNG_HR, NVL(A.AVG_PRCS_HR, 0) AS PRCS_HR FROM PMOWN.TN_PM_SMLT_RSLT_DTL A INNER JOIN PMOWN.TN_PM_SMLT_PSG_FCLT B ON A.PSG_FCLT_CD = B.PSG_FCLT_CD WHERE 1 = 1 AND A.SMLT_ID = #{smltId} AND B.TMNL_ID = #{tmnlId} AND B.USE_YN = 'Y' AND B.UP_PSG_FCLT_CD = #{upPsgFcltCd}
AND A.SMLT_MDL_SN = #{smltMdlSn}
ORDER BY A.SMLT_ACTL_DT, B.PSG_FCLT_CD

/* CastChknMapper.retrieveChknBoothOperList */ SELECT SUBSTR(X.CKNCT_ID, 1, 1) AS ISLAND, X.CKNCT_ID, X.BGN_DT, X.END_DT FROM (
SELECT Y.CKNCT_ID, TO_DATE(Y.OPER_YMD || Y.STA_HM, 'YYYYMMDDHH24MI') AS BGN_DT, TO_DATE( CASE WHEN Y.RON_YN = 'N' THEN Y.OPER_YMD ELSE TO_CHAR(TO_DATE(Y.OPER_YMD, 'YYYYMMDD') + 1, 'YYYYMMDD') END || Y.END_HM, 'YYYYMMDDHH24MI' ) AS END_DT FROM ( SELECT A.CKNCT_ID, A.OPER_YMD, NVL(A.EST_BGNG_HM, A.LAST_BGNG_HM) AS STA_HM, NVL(A.EST_END_HM, A.LAST_END_HM) AS END_HM, CASE WHEN TO_NUMBER(NVL(A.EST_BGNG_HM, A.LAST_BGNG_HM)) > TO_NUMBER(NVL(A.EST_END_HM, A.LAST_END_HM)) THEN 'Y' ELSE CASE WHEN NVL(A.EST_BGNG_HM, A.LAST_BGNG_HM) IS NOT NULL AND NVL(A.EST_END_HM, A.LAST_END_HM) IS NOT NULL THEN CASE WHEN A.LAST_BGNG_HM IS NOT NULL AND A.LAST_END_HM IS NOT NULL THEN A.LAST_RON_YN ELSE A.EST_RON_YN END ELSE A.EST_RON_YN END END AS RON_YN FROM GOOWN.TI_GO_CKNCT_DALY_ALOT A INNER JOIN CAOWN.TN_CA_CKNCT CIC ON A.CKNCT_ID = CIC.CKNCT_ID AND A.TMNL_ID = CIC.TMNL_ID WHERE A.USE_YN = 'Y' AND CIC.USE_YN = 'Y' AND CIC.CKNCT_USE_CRG_APLCN_TYPE_CD IN ('A', 'B') AND A.TMNL_ID = #{tmnlId} AND A.OPER_YMD BETWEEN TO_CHAR(TO_DATE(#{excnYmd}, 'YYYYMMDD') - 1, 'YYYYMMDD') AND #{excnYmd} AND A.CKNCT_ID NOT LIKE 'X%' AND A.CKNCT_ID NOT LIKE 'Y%' AND A.CKNCT_ID NOT LIKE 'R%' AND A.CKNCT_ID NOT LIKE 'S%' AND EXISTS ( SELECT 1 FROM CAOWN.TN_CA_ALN_PGE B WHERE B.ALN_CD = A.ALN_CD AND B.PGE_NO = A.CHKN_PGE_NO AND B.TMNL_ID = A.TMNL_ID AND B.USE_YN = 'Y' ) ) Y WHERE Y.STA_HM IS NOT NULL AND Y.END_HM IS NOT NULL AND Y.STA_HM != Y.END_HM
SELECT A.CKNCT_ID, TO_DATE(A.CHKN_OPEN_PRNMNT_DT, 'YYYYMMDDHH24MI') AS BGN_DT, TO_DATE(A.CHKN_CLOSE_PRNMNT_DT, 'YYYYMMDDHH24MI') AS END_DT FROM PMOWN.TN_PM_SMLT_CKNCT_ATRB A WHERE A.SCHDL_ATRB_GROUP_ID = REPLACE(#{cknctAlctnRsrcId}, 'CA', '') AND A.TMNL_ID = #{tmnlId} AND A.CHKN_OPEN_PRNMNT_DT IS NOT NULL AND A.CHKN_CLOSE_PRNMNT_DT IS NOT NULL
) X ORDER BY ISLAND, X.CKNCT_ID, X.BGN_DT

/* CastChknMapper.retrieveAlnCdList */
SELECT DISTINCT A.ALN_CD
FROM GOOWN.TI_GO_CKNCT_DALY_ALOT A
WHERE 1 = 1
AND A.OPER_YMD = #{ymd}
AND A.TMNL_ID = #{tmnlId}
AND A.USE_YN = 'Y'
ORDER BY A.ALN_CD

/* CastChknMapper.retrieveUserChknIslandList */
SELECT
    A.CHKN_ISL_CD AS ISLAND,
    NVL(A.BOOTH_CNT, 0) AS BOOTH_CNT,
    NVL(A.KOS_CNT, 0) AS KIOSK_CNT,
    NVL(A.SBD_CNT, 0) AS BAG_DROP_CNT
FROM PMOWN.TN_PM_SMLT_USER_CHKN_ISL A
WHERE 1 = 1
AND A.OWNER_USER_ID = #{loginUserId}
AND A.EXCN_YMD = #{ymd}
AND A.TMNL_ID = #{fcltTmnlId}
ORDER BY A.CHKN_ISL_CD

/* CastChknMapper.retrieveUserChknOperHrList */
SELECT
    A.CHKN_ISL_CD AS ISLAND,
    NVL(A.OPER_BGNG_HOUR, 0) AS OPER_BGNG_HOUR,
    NVL(A.OPER_END_HOUR, 0) AS OPER_END_HOUR
FROM PMOWN.TN_PM_SMLT_USER_CHKN_OPER_HR A
WHERE 1 = 1
AND A.OWNER_USER_ID = #{loginUserId}
AND A.EXCN_YMD = #{ymd}
AND A.TMNL_ID = #{fcltTmnlId}
ORDER BY A.CHKN_ISL_CD, A.OPER_HR_SN

/* CastChknMapper.retrieveUserChknBoothList */
SELECT
    A.CHKN_ISL_CD AS ISLAND,
    A.BOOTH_NO,
    A.ALN_CD,
    A.CSTM_ALTMNT_YN AS CSTM_ALTMNT_YN
FROM PMOWN.TN_PM_SMLT_USER_CHKN_BOOTH A
WHERE 1 = 1
AND A.OWNER_USER_ID = #{loginUserId}
AND A.EXCN_YMD = #{ymd}
AND A.TMNL_ID = #{fcltTmnlId}
ORDER BY A.CHKN_ISL_CD, A.BOOTH_NO

mapper.delete:
/* CastChknMapper.deleteUserChknIslandList */
DELETE FROM PMOWN.TN_PM_SMLT_USER_CHKN_ISL
WHERE 1 = 1
AND OWNER_USER_ID = #{loginUserId}
AND EXCN_YMD = #{ymd}
AND TMNL_ID = #{fcltTmnlId}

/* CastChknMapper.deleteUserChknOperHrList */
DELETE FROM PMOWN.TN_PM_SMLT_USER_CHKN_OPER_HR
WHERE 1 = 1
AND OWNER_USER_ID = #{loginUserId}
AND EXCN_YMD = #{ymd}
AND TMNL_ID = #{fcltTmnlId}

/* CastChknMapper.deleteUserChknBoothList */
DELETE FROM PMOWN.TN_PM_SMLT_USER_CHKN_BOOTH
WHERE 1 = 1
AND OWNER_USER_ID = #{loginUserId}
AND EXCN_YMD = #{ymd}
AND TMNL_ID = #{fcltTmnlId}

mapper.insert:
/* CastChknMapper.insertUserChknIslandList */ INSERT ALL
INTO PMOWN.TN_PM_SMLT_USER_CHKN_ISL ( OWNER_USER_ID, EXCN_YMD, TMNL_ID, CHKN_ISL_CD, BOOTH_CNT, KOS_CNT, SBD_CNT, FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT ) VALUES ( #{loginUserId}, #{ymd}, #{fcltTmnlId}, #{island.island}, #{island.boothCnt}, #{island.kioskCnt}, #{island.bagDropCnt}, #{loginUserId}, #{loginIpAddr}, CURRENT_TIMESTAMP )
SELECT 1 FROM DUAL

/* CastChknMapper.insertUserChknOperHrList */ INSERT ALL
INTO PMOWN.TN_PM_SMLT_USER_CHKN_OPER_HR ( OWNER_USER_ID, EXCN_YMD, TMNL_ID, CHKN_ISL_CD, OPER_HR_SN, OPER_BGNG_HOUR, OPER_END_HOUR, FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT ) VALUES ( #{loginUserId}, #{ymd}, #{fcltTmnlId}, #{island.island}, #{oprTimeIdx} + 1, #{oprTime.operBgngHour}, #{oprTime.operEndHour}, #{loginUserId}, #{loginIpAddr}, CURRENT_TIMESTAMP )
SELECT 1 FROM DUAL

/* CastChknMapper.insertUserChknBoothList */ INSERT ALL
INTO PMOWN.TN_PM_SMLT_USER_CHKN_BOOTH ( OWNER_USER_ID, EXCN_YMD, TMNL_ID, CHKN_ISL_CD, BOOTH_NO, ALN_CD, CSTM_ALTMNT_YN, FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT ) VALUES ( #{loginUserId}, #{ymd}, #{fcltTmnlId}, #{island.island}, #{booth.boothNo}, #{booth.alnCd}, #{booth.cstmAltmntYn}, #{loginUserId}, #{loginIpAddr}, CURRENT_TIMESTAMP )
SELECT 1 FROM DUAL
